/**
 * @summary Submit a recording
 */
export const getSubmitRecordingUrl = () => {
  return `/api/user/recordings`;
};

export const submitRecording = async (
  submitRecordingBody: SubmitRecordingBody,
  options?: RequestInit,
): Promise<RecordingInfo> => {
  const formData = new FormData();
  formData.append(`sentenceId`, submitRecordingBody.sentenceId.toString());
  formData.append(`sessionId`, submitRecordingBody.sessionId.toString());
  formData.append(`audio`, submitRecordingBody.audio);

  return customFetch<RecordingInfo>(getSubmitRecordingUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

